using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using NativeVideo;
public static class RuntimePersistenceChecks {
 static int checks;static string root;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 static void Put(string p,string s){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,s,Files.Utf8);}
 static void Throws(Action action,string label){try{action();}catch{checks++;return;}throw new Exception("Expected rejection: "+label);}
 static object Music(int players){return J.O("schemaVersion",2,"enabled",true,"players",players,"tracks",new object[0]);}
#if !CRAFT
