 #if !CRAFT
 static void MusicAtomicBoundaryChecks(){string games=Path.Combine(root,"atomic-games"),project=Path.Combine(games,"demo"),file=Path.Combine(project,"video-project.json");Directory.CreateDirectory(project);string first=J.Text(Music(1)),foreign=J.Text(Music(2)),ours=J.Text(Music(3)),later=J.Text(Music(4));Put(file,first);string expected=Files.Hash(file);Put(file,foreign);var atomic=typeof(MusicProjectStore).GetMethod("AtomicSave",BindingFlags.Static|BindingFlags.NonPublic);Throws(()=>atomic.Invoke(null,new object[]{file,ours,expected,"games/demo/video-project.json"}),"late atomic preimage conflict");string tx=Path.Combine(project,".webvideo-plus/music-transactions");Check(Directory.GetFiles(tx,"*.previous").Any(p=>File.ReadAllText(p)==foreign),"actual displaced foreign bytes preserved");Check(Directory.GetFiles(Path.Combine(project,".webvideo-plus/backups"),"*.json").Select(J.Read).Any(b=>J.S(b,"before")==foreign),"late foreign version discoverable by backup UI");Put(file,later);MusicProjectStore.Read(games,J.O("project","demo"));Check(File.ReadAllText(file)==later,"later foreign write never auto-rolled back");string id=Guid.NewGuid().ToString(),previous=Path.Combine(tx,id+".previous"),temp=Path.Combine(project,".wvp-music-"+id+".tmp"),journal=Path.Combine(tx,id+".pending.json");Put(file,foreign);Put(temp,ours);J.Write(journal,J.O("id",id,"target",Path.GetFullPath(file),"previous",previous,"temp",temp,"expectedHash",expected,"newHash",Files.HashText(ours),"projectPath","games/demo/video-project.json"));File.Replace(temp,file,previous);Put(file,later);var recovered=MusicProjectStore.Read(games,J.O("project","demo"));Check(J.S(recovered,"error")!=""&&File.ReadAllText(file)==later,"crash recovery retains a newer external write");Check(File.ReadAllText(previous)==foreign,"crash preimage retained");string bad=Path.Combine(games,"fail");Directory.CreateDirectory(bad);Put(Path.Combine(bad,".webvideo-plus/backups"),"sentinel");Throws(()=>MusicProjectStore.Save(games,J.O("project","fail","expectedHash","missing","music",Music(1))),"backup write failure");Check(!File.Exists(Path.Combine(bad,"video-project.json"))&&File.ReadAllText(Path.Combine(bad,".webvideo-plus/backups"))=="sentinel","backup failure retains target and neighbor");}
