 static void PreparationChecks(){string jobs=Path.Combine(root,"prep/jobs"),work=Path.Combine(root,"prep/work");Directory.CreateDirectory(jobs);Directory.CreateDirectory(work);Put(Path.Combine(work,"neighbor.txt"),"keep");string id=Guid.NewGuid().ToString(),record=Path.Combine(jobs,id),cache=Path.Combine(work,id);using(var p=new QueuePreparation(record,cache)){Put(Path.Combine(cache,"partial.bin"),"partial");}Check(!Directory.Exists(record)&&!Directory.Exists(cache),"failed preparation reclaimed");Check(File.ReadAllText(Path.Combine(work,"neighbor.txt"))=="keep","neighbor retained");id=Guid.NewGuid().ToString();record=Path.Combine(jobs,id);cache=Path.Combine(work,id);var abandoned=new QueuePreparation(record,cache);Put(Path.Combine(cache,"partial.bin"),"partial");QueuePreparation.Recover(jobs,work);Check(!Directory.Exists(record)&&!Directory.Exists(cache),"restart reclaimed owned preparation");id=Guid.NewGuid().ToString();record=Path.Combine(jobs,id);cache=Path.Combine(work,id);using(var p=new QueuePreparation(record,cache)){J.Write(Path.Combine(record,"request.json"),J.O("id",id));p.Commit();}QueuePreparation.Recover(jobs,work);Check(File.Exists(Path.Combine(record,"request.json")),"committed request retained");id=Guid.NewGuid().ToString();record=Path.Combine(jobs,id);cache=Path.Combine(work,id);var mismatch=new QueuePreparation(record,cache);Put(Path.Combine(cache,".preparing.json"),"{}");QueuePreparation.Recover(jobs,work);Check(Directory.Exists(cache)&&Directory.Exists(record),"ownership mismatch retained");Throws(()=>new QueuePreparation(record,cache),"existing directory");}
 static void MapChecks(){string data=Path.Combine(root,"selected-data");Put(Path.Combine(data,"character-map/characters.json"),J.Text(J.O("schemaVersion",1,"rows",new[]{J.O("names","测试角色","id","selected") })));string games=Path.Combine(root,"map-games"),figures=Path.Combine(games,"demo/game/figure");Put(Path.Combine(figures,"selected/model.json"),"{\"FileReferences\":{}}");Directory.CreateDirectory(Path.Combine(games,"demo/game/background"));var provider=new AiProviderStore(data);var method=typeof(AiProviderStore).GetMethod("CollectStageAssets",BindingFlags.NonPublic|BindingFlags.Instance);var assets=method.Invoke(provider,new object[]{games,"demo",new[]{"测试角色"},null});Check(J.S(J.A(J.Get(assets,"actors"))[0],"id")=="selected","configured mapping root");var frozen=new CharacterMapStore(data).Read();Put(Path.Combine(data,"character-map/characters.json"),J.Text(J.O("schemaVersion",1,"rows",new[]{J.O("names","测试角色","id","changed") })));assets=method.Invoke(provider,new object[]{games,"demo",new[]{"测试角色"},J.Parse(J.Text(frozen))});Check(J.S(J.A(J.Get(assets,"actors"))[0],"id")=="selected","persisted mapping snapshot retained");}
 static void QueueChecks(){string state=Path.Combine(root,"queue/state"),work=Path.Combine(root,"queue/work"),games=Path.Combine(root,"queue/games"),terre=Path.Combine(root,"queue/terre");Put(Path.Combine(state,"user-data/fixture.txt"),"prevent legacy user data import");Put(Path.Combine(games,"demo/game/scene/start.txt"),":fixture;");Directory.CreateDirectory(terre);Directory.CreateDirectory(work);Put(Path.Combine(work,"neighbor.txt"),"keep");var q=new QueueService(J.O("stateDir",state,"gamesRoot",games,"terreDir",terre,"workDir",work,"outputDir",Path.Combine(root,"queue/output"),"modules",new[]{"subtitles"},"importLegacyUserData",false));typeof(QueueService).GetField("stopping",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(q,true);var method=typeof(QueueService).GetMethod("Authorized",BindingFlags.Instance|BindingFlags.NonPublic);Func<object,HttpResponse> send=requestBody=>((Task<HttpResponse>)method.Invoke(q,new object[]{new HttpRequest{Path="/api/jobs",Method="POST",Body=Encoding.UTF8.GetBytes(J.Text(requestBody))}})).GetAwaiter().GetResult();var body=J.O("project","demo","scene","start.txt","sourceText",":fixture;","fileName","test.mp4","useMusicTimeline",false,"settings",J.O("gpuRawMode","traditional","engine","webgal"),"subtitle",J.O("sourcePath",Path.Combine(root,"missing.srt"),"mode","soft","anchor",J.O("type","video")),"requestId",Guid.NewGuid().ToString());Throws(()=>send(body),"prepare subtitle failure");Check(Directory.GetDirectories(Path.Combine(state,"jobs")).Length==0&&Directory.GetDirectories(work).Length==0,"actual enqueue failure reclaimed directories");Check(File.ReadAllText(Path.Combine(work,"neighbor.txt"))=="keep","enqueue neighbor retained");body.Remove("subtitle");var response=send(body);string id=J.S(response.Json,"id");Check(id!=""&&File.Exists(Path.Combine(state,"jobs",id,"request.json")),"actual enqueue published request");Check(J.S(send(body).Json,"id")==id&&Directory.GetDirectories(Path.Combine(state,"jobs")).Length==1,"idempotent repeated enqueue");body["fileName"]="different.mp4";Throws(()=>send(body),"request ID payload conflict");q.Stop();}
 static object Wait(AiProviderStore provider,string id){for(int i=0;i<400;i++){var state=provider.NovelStatus(J.O("id",id));if(J.S(state,"state")!="running")return state;Thread.Sleep(25);}throw new Exception("mock AI did not finish");}
 static void Configure(AiProviderStore p,string model="mock"){p.Save(J.O("provider","custom","baseURL","http://127.0.0.1:1","api","openai-completions","model",model,"key","local-fixture-key","autoRouting",false));}
 static object Input(){var units=Enumerable.Range(0,100).Select(i=>(object)J.O("id",i,"text","a")).ToArray();return J.O("project","demo","source",new string('a',100),"units",units,"knownSpeakers",new object[0]);}
 static void AiChecks(){string data=Path.Combine(root,"ai-data"),games=Path.Combine(root,"ai-games"),control=Path.Combine(root,"mock-control.json"),calls=Path.Combine(root,"mock-calls.jsonl");Directory.CreateDirectory(Path.Combine(games,"demo/game/figure"));Directory.CreateDirectory(Path.Combine(games,"demo/game/background"));Environment.SetEnvironmentVariable("WEBVIDEO_TEST_MOCK",control);J.Write(control,J.O("failStageAt",45,"calls",calls));var p=new AiProviderStore(data);Configure(p);string id=J.S(p.StartNovel(Input(),games),"id");var failed=Wait(p,id);Check(J.S(failed,"state")=="failed","stage failure surfaced");string task=Path.Combine(data,"ai/novel-tasks",id);Check(File.Exists(Path.Combine(task,"structure.json"))&&File.Exists(Path.Combine(task,"stage-0.json")),"stage boundary and batch persisted");Check(!Directory.GetFiles(task,"*.json").Any(f=>File.ReadAllText(f).Contains("local-fixture-key")),"credential omitted from task files");J.Write(control,J.O("calls",calls));var restarted=new AiProviderStore(data);Check(J.S(restarted.NovelStatus(J.O("id",id)),"state")=="failed","status survives store restart");Check(J.S(restarted.StartNovel(Input(),games),"id")==id,"same task resumed");var complete=Wait(restarted,id);Check(J.S(complete,"state")=="complete","stage resume completes");var rows=File.ReadAllLines(calls).Select(J.Parse).ToArray();Check(rows.Count(r=>J.S(r,"action")=="novel")==1,"completed structure not regenerated");Check(rows.Count(r=>J.S(r,"action")=="stage"&&J.N(r,"at")==0)==1,"completed stage batch not regenerated");int count=rows.Length;Check(J.S(new AiProviderStore(data).NovelStatus(J.O("id",id)),"state")=="complete","completed task remains recoverable");Check(File.ReadAllLines(calls).Length==count,"status recovery makes no model call");var again=new AiProviderStore(data);string againId=J.S(again.StartNovel(Input(),games),"id");Check(againId!=id,"user can generate again after completion");Check(J.S(Wait(again,againId),"state")=="complete","fresh generation completes");var nextInput=J.D(Input());nextInput["fromScratch"]=true;J.Write(control,J.O("delayMs",400,"calls",calls));var cancelProvider=new AiProviderStore(data);string cancelId=J.S(cancelProvider.StartNovel(nextInput,games),"id");cancelProvider.CancelNovel(J.O("id",cancelId));Check(J.S(Wait(cancelProvider,cancelId),"state")=="cancelled","cancel persisted");Thread.Sleep(100);Check(J.S(new AiProviderStore(data).NovelStatus(J.O("id",cancelId)),"state")=="cancelled","cancel tombstone survives restart");}
 public static int Main(string[] args){try{root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Files.Root=Path.Combine(root,"runtime");
#if !CRAFT
 MusicChecks();MusicRecoveryChecks();MusicAtomicBoundaryChecks();
#endif
 PreparationChecks();QueueChecks();MapChecks();AiChecks();Console.WriteLine(J.Text(J.O("ok",true,"checks",checks)));return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
